ST.xhtml:
// =============================================================================
// 场景：MES 配方表里"通信配置"字段是 hex 字面量字符串（'FF01' 表示寄存器
//       高字节 0xFF 低字节 0x01）。PLC 端按 nibble 解析后写入控制寄存器。
// 价值：从 STRING 字面解析时本函数语义比 HEXASCNIBBLE_TO_BYTE 更直观，
//       不必先做 STRING -> 字节数组转换；大小写不敏感、错误统一返回 255。
// 验证步骤：
//   1. 登录后 sMesHexConfig = 'FF01'。
//   2. 写 bParseRequest := TRUE 触发解析。
//   3. 观察 bConfigByte0 = 0xFF = 255，bConfigByte1 = 0x01 = 1。
//   4. 把 sMesHexConfig 改成 'ff01'（小写），重新触发：结果完全一致，
//      印证 §3 大小写不敏感。
//   5. 把 sMesHexConfig 改成 'FG01'（含非 hex 字符 G），观察 bConfigByte0
//      变为 0xF5 = SHL(15,4) OR 255 = ... 即检测到非法字符（实际是合成出错）；
//      工程上需检 nibble = 255 判错（见 HEXASCNIBBLE 例程）。
// =============================================================================

IF bParseRequest THEN
    // 用 MID 抽四个单字符再调本函数得到 4 个 nibble
    // 再两两 SHL+OR 合成两个字节
    bConfigByte0 := SHL(HEXCHRNIBBLE_TO_BYTE(MID(sMesHexConfig, 1, 1)), 4)
                  OR HEXCHRNIBBLE_TO_BYTE(MID(sMesHexConfig, 1, 2));
    bConfigByte1 := SHL(HEXCHRNIBBLE_TO_BYTE(MID(sMesHexConfig, 1, 3)), 4)
                  OR HEXCHRNIBBLE_TO_BYTE(MID(sMesHexConfig, 1, 4));
    bParseRequest := FALSE;
END_IF;
